/* From Uiverse.io by vinodjangid07  - Tags: switch, neon, toggle, power on */
.__UIV_SCOPE__ #checkbox {
  display: none;
}

.__UIV_SCOPE__ .switch {
  position: relative;
  width: 70px;
  height: 70px;
  background-color: rgb(99, 99, 99);
  border-radius: 50%;
  z-index: 1;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid rgb(126, 126, 126);
  box-shadow: 0px 0px 3px rgb(2, 2, 2) inset;
}
.__UIV_SCOPE__ .switch svg {
  width: 1.2em;
}
.__UIV_SCOPE__ .switch svg path {
  fill: rgb(48, 48, 48);
}
.__UIV_SCOPE__ #checkbox:checked + .switch {
  box-shadow: 0px 0px 1px rgb(151, 243, 255) inset,
    0px 0px 2px rgb(151, 243, 255) inset, 0px 0px 10px rgb(151, 243, 255) inset,
    0px 0px 40px rgb(151, 243, 255), 0px 0px 100px rgb(151, 243, 255),
    0px 0px 5px rgb(151, 243, 255);
  border: 2px solid rgb(255, 255, 255);
  background-color: rgb(146, 180, 184);
}
.__UIV_SCOPE__ #checkbox:checked + .switch svg {
  filter: drop-shadow(0px 0px 5px rgb(151, 243, 255));
}
.__UIV_SCOPE__ #checkbox:checked + .switch svg path {
  fill: rgb(255, 255, 255);
}
